<?php // Databasdump till en SQL-fil (används av uppdateringssidan och bakgrundsjobbet dbbackup.php). $prog($text) rapporterar förlopp.
function vm_dump_db($file,$prog){ $pdo=db(); $h=@fopen($file,'wb'); if(!$h) throw new Exception(t('Kan inte skriva databasdumpen','Cannot write the database dump'));
 fwrite($h,"-- VM Monitor database dump ".date('Y-m-d H:i:s')." (version ".VMMON_VERSION.")\nSET FOREIGN_KEY_CHECKS=0;\nSET NAMES utf8mb4;\n");
 $tabs=$pdo->query("SHOW FULL TABLES WHERE Table_type='BASE TABLE'")->fetchAll(PDO::FETCH_NUM); $est=[]; try{ foreach($pdo->query('SELECT TABLE_NAME n,TABLE_ROWS r FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()') as $x) $est[$x['n']]=(int)$x['r']; }catch(Throwable $e){} $prog(sprintf(t('Databasen: %d tabeller, ungefär %s rader','Database: %d tables, about %s rows'),count($tabs),number_format(array_sum($est),0,',',' '))); $buf=$pdo->getAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY); $pdo->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,false);
 try{ foreach($tabs as $t0){ $t=$t0[0]; $q='`'.str_replace('`','``',$t).'`'; $cr=$pdo->query('SHOW CREATE TABLE '.$q)->fetchAll(PDO::FETCH_NUM)[0]; $ddl=preg_replace('/\s*\r?\n\s*/',' ',(string)$cr[1]);
   fwrite($h,"DROP TABLE IF EXISTS $q;\n$ddl;\n"); $rs=$pdo->query('SELECT * FROM '.$q); $rows=[]; $n=0; $big=($est[$t]??0)>50000; if($big) $prog(sprintf(t('Tabellen %s: ungefär %s rader','Table %s: about %s rows'),$t,number_format($est[$t],0,',',' ')));
   while($r=$rs->fetch(PDO::FETCH_NUM)){ if($big&&++$n%200000===0) $prog(sprintf('%s: %s %s',$t,number_format($n,0,',',' '),t('rader','rows'))); $rows[]='('.implode(',',array_map(function($v) use($pdo){ return $v===null?'NULL':$pdo->quote((string)$v); },$r)).')'; if(count($rows)>=200){ fwrite($h,"INSERT INTO $q VALUES ".implode(',',$rows).";\n"); $rows=[]; } }
   $rs->closeCursor(); if($rows) fwrite($h,"INSERT INTO $q VALUES ".implode(',',$rows).";\n");  if($big) $prog(sprintf('%s: %s (%s %s)',$t,t('klar','done'),number_format($n,0,',',' '),t('rader','rows'))); }
 } finally { $pdo->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,$buf); } fwrite($h,"SET FOREIGN_KEY_CHECKS=1;\n"); fclose($h); }
